  "audit-trail": AuditTrailSchema,
  "confirmation-panel": ConfirmationPanelSchema,
  "risk-review-panel": RiskReviewPanelSchema,
  "diff-viewer": DiffViewerSchema,
  "source-evidence-panel": SourceEvidencePanelSchema,
  "dynamic-question-flow": DynamicQuestionFlowSchema,
  "extracted-fields-review": ExtractedFieldsReviewSchema,
  "comparison-matrix": ComparisonMatrixSchema,
  "score-breakdown": ScoreBreakdownSchema,
  "tool-call-card": ToolCallCardSchema,
  "retryable-error-state": RetryableErrorStateSchema,
  "auth-required-card": AuthRequiredCardSchema,
  "approval-checklist": ApprovalChecklistSchema,
  "before-submit-confirmation": BeforeSubmitConfirmationSchema,
  "destructive-action-guard": DestructiveActionGuardSchema,
  "human-override-panel": HumanOverridePanelSchema,
  "permission-request-card": PermissionRequestCardSchema,
  "tool-result-card": ToolResultCardSchema,
  "running-task-card": RunningTaskCardSchema,
  "partial-result-viewer": PartialResultViewerSchema,
  "queued-step-list": QueuedStepListSchema,
  "tool-trace-viewer": ToolTraceViewerSchema,
  "missing-data-request": MissingDataRequestSchema,
  "multi-step-form": MultiStepFormSchema,
  "inline-edit-form": InlineEditFormSchema,
  "form-progress-card": FormProgressCardSchema,
  "validated-field-list": ValidatedFieldListSchema,
  "document-preview": DocumentPreviewSchema,
  "file-review": FileReviewSchema,
  "source-list": SourceListSchema,
  "evidence-drawer": EvidenceDrawerSchema,
  "record-inspector": RecordInspectorSchema,
  "field-confidence-list": FieldConfidenceListSchema,
  "conflict-resolver": ConflictResolverSchema,
  "validation-summary": ValidationSummarySchema,
  "option-selector": OptionSelectorSchema,
  "ranking-list": RankingListSchema,
  "billing-gate": BillingGateSchema,
  "unsupported-host-notice": UnsupportedHostNoticeSchema,
  "no-data-state": NoDataStateSchema,
  "loading-bridge-state": LoadingBridgeStateSchema,
  "offline-state": OfflineStateSchema,
  "permission-denied-state": PermissionDeniedStateSchema,
  "expired-session-state": ExpiredSessionStateSchema
} as const;

"use client";

import { useState, type FormEvent } from "react";
import type { MCPCNSecurityManifest } from "./core";
import { ApprovalCardSchema, AuditTrailSchema, EntityReviewTableSchema, GenericComponentSchema, SchemaFormSchema, ToolProgressTimelineSchema, type ApprovalCardData, type AuditTrailData, type EntityReviewTableData, type ParsedApprovalCardData, type SchemaFormData, type ToolProgressTimelineData } from "./schemas";
import { Button, Card, Badge, Input, Textarea, Select, InvalidPayload } from "./primitives.js";
import { Feedback, revisionKey, useComponentAction } from "./component-helpers.js";
import type { ComponentProps } from "./component-types.js";

export type { ComponentAction, ComponentProps } from "./component-types.js";
export { Button, Card, Badge, Input, Textarea, Select, Alert, Skeleton, EmptyState, Tabs, Dialog, Tooltip, InvalidPayload } from "./primitives.js";
export { ConfirmationPanel, RiskReviewPanel, DiffViewer, SourceEvidencePanel } from "./review-components.js";
export { DynamicQuestionFlow, ExtractedFieldsReview, ComparisonMatrix, ScoreBreakdown } from "./decision-components.js";
export { ToolCallCard, RetryableErrorState, AuthRequiredCard } from "./execution-components.js";
export { ApprovalChecklist, BeforeSubmitConfirmation, DestructiveActionGuard, HumanOverridePanel, PermissionRequestCard } from "./approval-components.js";
export { ToolResultCard, RunningTaskCard, PartialResultViewer, QueuedStepList, ToolTraceViewer } from "./tool-workflow-components.js";
export { MissingDataRequest, MultiStepForm, InlineEditForm, FormProgressCard, ValidatedFieldList } from "./form-workflow-components.js";
export { DocumentPreview, FileReview } from "./file-review-components.js";
export { SourceList, EvidenceDrawer } from "./source-evidence-components.js";
export { RecordInspector, FieldConfidenceList } from "./record-inspection-components.js";
export { ConflictResolver, ValidationSummary } from "./conflict-validation-components.js";
export { OptionSelector, RankingList } from "./option-ranking-components.js";
export { BillingGate, UnsupportedHostNotice, NoDataState, LoadingBridgeState, OfflineState, PermissionDeniedState, ExpiredSessionState } from "./host-state-components.js";
export { RecommendationCard, TradeoffPanel, DecisionMemo, ReasoningSummary, decisionNarrativeIntent } from "./decision-narrative-components.js";
export { DataAccessNotice, PrivacyBoundaryCard, ConsentPanel, ModelContextPreview, privacyContextIntent } from "./privacy-context-components.js";

export const ApprovalCardSecurity: MCPCNSecurityManifest = { modelVisible:["decision","reason"], privateOnly:["internalRecordId"], callsTools:["approvalTool"], destructive:true };
export function ApprovalCard(props: ComponentProps<ApprovalCardData>) {
  const parsed = ApprovalCardSchema.safeParse(props);
  if (!parsed.success) return <InvalidPayload title="Approval card could not be rendered" issues={parsed.error.issues.map(issue => issue.path.join(".") + ": " + issue.message)} />;
  return <ApprovalCardView key={revisionKey(parsed.data)} data={parsed.data} props={props} />;
}
function ApprovalCardView({ data, props }: { data: ParsedApprovalCardData; props: ComponentProps<ApprovalCardData> }) {
  const [consent, setConsent] = useState(false);
  const { send, busy, error } = useComponentAction(props.onAction, props.busy);
  const blocked = data.requiresExplicitConsent && !consent;
  return <Card className={props.className} aria-busy={busy}>
    <div className="mcpcn-header"><div className="mcpcn-row mcpcn-between"><h3 className="mcpcn-title">{data.title}</h3><Badge risk={data.riskLevel}>{data.riskLevel} risk</Badge></div>{data.description && <p className="mcpcn-description">{data.description}</p>}</div>
    <div className="mcpcn-body">
      {data.changes.length ? <div>{data.changes.map((change, index) => <div className="mcpcn-change" key={change.label + "-" + index}><strong>{change.label}</strong><span><span className="mcpcn-before">{String(change.before ?? "—")}</span> → <span className="mcpcn-after">{String(change.after ?? "—")}</span></span><span className="mcpcn-hint">{change.affectedCount !== undefined ? change.affectedCount + " affected" : change.confidence !== undefined ? Math.round(change.confidence * 100) + "% confidence" : ""}</span></div>)}</div> : <p className="mcpcn-description">No field-level changes were provided.</p>}
      {data.rollback && <p className="mcpcn-hint">Rollback: {data.rollback}</p>}
      {data.requiresExplicitConsent && <label className="mcpcn-row" style={{ marginTop: 14 }}><input type="checkbox" checked={consent} disabled={busy} onChange={event => setConsent(event.currentTarget.checked)} />{data.consentLabel ?? "I understand the impact of this action."}</label>}
      <Feedback busy={busy} error={props.error ?? error} />
    </div>
    <div className="mcpcn-footer mcpcn-row" style={{ justifyContent: "flex-end" }}>
      <Button type="button" data-variant="secondary" disabled={busy || !props.onAction} onClick={() => send({ type: "cancel" })}>{data.cancelLabel}</Button>
      <Button type="button" data-variant={data.riskLevel === "critical" ? "danger" : undefined} disabled={busy || blocked || !props.onAction} onClick={() => { if (!blocked) send({ type: "approve", data: { tool: data.approvalTool } }); }}>{busy ? "Working…" : data.actionLabel}</Button>
    </div>
  </Card>;
}

export function ToolProgressTimeline(props: ComponentProps<ToolProgressTimelineData>) { const parsed=ToolProgressTimelineSchema.safeParse(props); if(!parsed.success)return <InvalidPayload title="Progress data is invalid" issues={parsed.error.issues.map(i=>i.message)} />; const data=parsed.data; return <Card className={props.className}><div className="mcpcn-header"><h3 className="mcpcn-title">{data.title}</h3>{data.description&&<p className="mcpcn-description">{data.description}</p>}</div><div className="mcpcn-body mcpcn-stack">{data.steps.map(step=><div className="mcpcn-progress" key={step.id}><span className="mcpcn-progress-line"><i className="mcpcn-dot" data-status={step.status}/></span><div style={{paddingBottom:12}}><div className="mcpcn-row mcpcn-between"><strong>{step.label}</strong><Badge>{step.status}</Badge></div>{step.description&&<div className="mcpcn-description">{step.description}</div>}{step.error&&<div style={{color:"var(--mcpcn-danger)"}}>{step.error}</div>}{step.status==="failed"&&data.retryTool&&<Button style={{marginTop:8}} data-variant="secondary" onClick={()=>props.onAction?.({type:"retry",data:{stepId:step.id,tool:data.retryTool}})}>Retry step</Button>}</div></div>)}</div></Card> }

export function SchemaForm(props: ComponentProps<SchemaFormData>) {
  const parsed = SchemaFormSchema.safeParse(props);
  if (!parsed.success) return <InvalidPayload title="Form schema is invalid" issues={parsed.error.issues.map(issue => issue.message)} />;
  return <SchemaFormView key={revisionKey(parsed.data)} data={parsed.data} props={props} />;
}
function SchemaFormView({ data, props }: { data: ReturnType<typeof SchemaFormSchema.parse>; props: ComponentProps<SchemaFormData> }) {
  const [values, setValues] = useState<Record<string, unknown>>(() => Object.fromEntries(data.fields.map(field => [field.name, field.value ?? (field.type === "boolean" ? false : "")])));
  const { send, busy, error } = useComponentAction(props.onAction, props.busy);
  const complete = data.fields.length > 0 && data.fields.every(field => {
    const value = values[field.name];
    if (field.type === "boolean") return typeof value === "boolean" && (!field.required || value);
    if (field.type === "number") return value === "" ? !field.required : typeof value === "number" && Number.isFinite(value);
    if (typeof value !== "string" || (field.required && !value.trim())) return false;
    return field.type !== "select" || value === "" || (field.options ?? []).some(option => option.value === value);
  });
  const change = (name: string, value: unknown) => { if (!busy) setValues(current => ({ ...current, [name]: value })); };
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (busy || !complete || !props.onAction || !event.currentTarget.checkValidity()) return;
    const allowed = Object.fromEntries(data.fields.map(field => [field.name, values[field.name]]));
    send({ type: "submit", data: { values: allowed, tool: data.submitTool } });
  };
  return <Card className={props.className} aria-busy={busy}><form aria-label={data.title} onSubmit={submit}>
    <div className="mcpcn-header"><h3 className="mcpcn-title">{data.title}</h3>{data.description && <p className="mcpcn-description">{data.description}</p>}</div>
    <fieldset disabled={busy} className="mcpcn-body mcpcn-stack" style={{ border: 0, margin: 0, minWidth: 0 }}>
      <legend className="mcpcn-sr-only">Fields to complete</legend>
      {!data.fields.length && <p role="status">No fields to complete.</p>}
      {data.fields.map(field => <label className="mcpcn-label" key={field.name}>{field.label}
        {field.type === "textarea" ? <Textarea aria-label={field.label} required={field.required} value={String(values[field.name] ?? "")} onChange={event => change(field.name, event.currentTarget.value)} />
          : field.type === "select" ? <Select aria-label={field.label} required={field.required} value={String(values[field.name] ?? "")} onChange={event => change(field.name, event.currentTarget.value)}><option value="">Select…</option>{field.options?.map(option => <option value={option.value} key={option.value}>{option.label}</option>)}</Select>
            : field.type === "boolean" ? <input type="checkbox" required={field.required} checked={values[field.name] === true} onChange={event => change(field.name, event.currentTarget.checked)} />
              : <Input type={field.type} step={field.type === "number" ? "any" : undefined} required={field.required} value={String(values[field.name] ?? "")} onChange={event => change(field.name, field.type === "number" ? event.currentTarget.value === "" ? "" : event.currentTarget.valueAsNumber : event.currentTarget.value)} />}
        {field.description && <span className="mcpcn-hint">{field.description}</span>}
      </label>)}
      <Feedback busy={busy} error={props.error ?? error} />
    </fieldset>
    <div className="mcpcn-footer" style={{ textAlign: "right" }}><Button type="submit" disabled={busy || !complete || !props.onAction}>{busy ? "Working…" : data.submitLabel}</Button></div>
  </form></Card>;
}

export function EntityReviewTable(props: ComponentProps<EntityReviewTableData>) { const parsed=EntityReviewTableSchema.safeParse(props); if(!parsed.success)return <InvalidPayload title="Review table data is invalid" issues={parsed.error.issues.map(i=>i.message)} />; const data=parsed.data; return <Card className={props.className}><div className="mcpcn-header"><h3 className="mcpcn-title">{data.title}</h3>{data.description&&<p className="mcpcn-description">{data.description}</p>}</div><div className="mcpcn-table-wrap"><table className="mcpcn-table"><thead><tr>{data.columns.map(c=><th key={c.key}>{c.label}</th>)}<th>Confidence</th></tr></thead><tbody>{data.rows.map(row=><tr key={row.id}>{data.columns.map(c=><td key={c.key}>{String(row.values[c.key]??"—")}</td>)}<td>{row.confidence===undefined?"—":`${Math.round(row.confidence*100)}%`}</td></tr>)}</tbody></table></div>{data.actionLabel&&<div className="mcpcn-footer" style={{textAlign:"right"}}><Button onClick={()=>props.onAction?.({type:"confirm",data:{tool:data.actionTool,ids:data.rows.map(r=>r.id)}})}>{data.actionLabel}</Button></div>}</Card> }

export function AuditTrail(props: ComponentProps<AuditTrailData>) { const parsed=AuditTrailSchema.safeParse(props); if(!parsed.success)return <InvalidPayload title="Audit trail is invalid" issues={parsed.error.issues.map(i=>i.message)} />; return <Card className={props.className}><div className="mcpcn-header"><h3 className="mcpcn-title">{parsed.data.title}</h3></div><ol className="mcpcn-body mcpcn-stack" style={{listStyle:"none",margin:0}}>{parsed.data.entries.map(e=><li key={e.id} className="mcpcn-row" style={{alignItems:"flex-start"}}><Badge>{e.status}</Badge><div><strong>{e.label}</strong>{e.description&&<div className="mcpcn-description">{e.description}</div>}<div className="mcpcn-hint">{e.actor&&`${e.actor} · `}<time dateTime={e.timestamp}>{e.timestamp}</time></div></div></li>)}</ol></Card> }


export type GenericAgentComponentProps = ComponentProps<{ title:string; description?:string; status?:string; items?:Array<Record<string,unknown>>; actions?:Array<{label:string;value:string;destructive?:boolean}>; [key:string]:unknown }>;
export function GenericAgentComponent(props: GenericAgentComponentProps) { const parsed=GenericComponentSchema.safeParse(props); if(!parsed.success)return <InvalidPayload issues={parsed.error.issues.map(i=>i.message)} />; const data=parsed.data; return <Card className={props.className}><div className="mcpcn-header"><div className="mcpcn-row mcpcn-between"><h3 className="mcpcn-title">{data.title}</h3>{data.status&&<Badge>{data.status}</Badge>}</div>{data.description&&<p className="mcpcn-description">{data.description}</p>}</div>{data.items&&<div className="mcpcn-body mcpcn-stack">{data.items.map((item,index)=><div key={index} className="mcpcn-change">{Object.entries(item).slice(0,3).map(([key,value])=><span key={key}><span className="mcpcn-hint">{key}</span><br/>{String(value)}</span>)}</div>)}</div>}{data.actions?.length?<div className="mcpcn-footer mcpcn-row" style={{justifyContent:"flex-end"}}>{data.actions.map(a=><Button key={a.value} data-variant={a.destructive?"danger":undefined} onClick={()=>props.onAction?.({type:a.value})}>{a.label}</Button>)}</div>:null}</Card> }

"use client";

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import type { DisplayMode, HostCapabilities, ToolResult } from "./core";
import { App as MCPApp } from "@modelcontextprotocol/ext-apps";

export type AgentAppSnapshot = {
  /** Official/OpenAI adapters expose raw arguments, not a notification envelope. */
  toolInput?: unknown;
  toolResult?: ToolResult;
  structuredContent?: unknown;
  meta?: Record<string, unknown>;
  displayMode: DisplayMode;
  theme?: "light" | "dark";
  widgetState?: unknown;
  capabilities: HostCapabilities;
};

export interface AgentAppAdapter {
  readonly kind: HostCapabilities["host"];
  connect?(listener: (snapshot: Partial<AgentAppSnapshot>) => void): () => void;
  callTool(name: string, args?: Record<string, unknown>): Promise<ToolResult>;
  sendMessage(message: string): Promise<void>;
  updateModelContext(context: unknown): Promise<void>;
  setWidgetState(state: unknown): Promise<void>;
  requestDisplayMode?(mode: DisplayMode): Promise<void>;
  getCapabilities(): HostCapabilities;
}

type RPCResponse = { jsonrpc: "2.0"; id?: number; result?: unknown; error?: { code: number; message: string } };

export class StandardMCPAdapter implements AgentAppAdapter {
  readonly kind = "standard-mcp" as const;
  private id = 0;
  private pending = new Map<number, { resolve: (value: unknown) => void; reject: (error: Error) => void }>();
  private target: Window;
  private origin: string;
  constructor(options: { target?: Window; origin?: string } = {}) {
    this.target = options.target ?? window.parent;
    this.origin = options.origin ?? "*";
  }
  private rpc(method: string, params?: unknown): Promise<unknown> {
    const id = ++this.id;
    this.target.postMessage({ jsonrpc: "2.0", id, method, params }, this.origin);
    return new Promise((resolve, reject) => this.pending.set(id, { resolve, reject }));
  }
  connect(listener: (snapshot: Partial<AgentAppSnapshot>) => void): () => void {
    const onMessage = (event: MessageEvent) => {
      if (this.origin !== "*" && event.origin !== this.origin) return;
      const message = event.data as RPCResponse & { method?: string; params?: Record<string, unknown> };
      if (!message || message.jsonrpc !== "2.0") return;
      if (typeof message.id === "number" && this.pending.has(message.id)) {
        const pending = this.pending.get(message.id)!;
        this.pending.delete(message.id);
        message.error ? pending.reject(new Error(message.error.message)) : pending.resolve(message.result);
      }
      if (message.method === "ui/notifications/tool-input") listener({ toolInput: message.params });
      if (message.method === "ui/notifications/tool-result") {
        const result = message.params as ToolResult;
        listener({ toolResult: result, structuredContent: result.structuredContent, meta: result._meta });
      }
      if (message.method === "ui/notifications/host-context-changed") {
        const mode = message.params?.displayMode;
        if (mode === "inline" || mode === "pip" || mode === "fullscreen") listener({ displayMode: mode });
      }
    };
    window.addEventListener("message", onMessage);
    void this.rpc("ui/initialize", { protocolVersion: "2026-01-26", appInfo: { name: "mcpcn-app", version: "0.1.0" }, appCapabilities: {} }).catch(() => undefined);
    return () => window.removeEventListener("message", onMessage);
  }
  async callTool(name: string, args: Record<string, unknown> = {}): Promise<ToolResult> { return await this.rpc("tools/call", { name, arguments: args }) as ToolResult; }
  async sendMessage(message: string): Promise<void> { await this.rpc("ui/message", { role: "user", content: [{ type: "text", text: message }] }); }
  async updateModelContext(context: unknown): Promise<void> { await this.rpc("ui/update-model-context", { content: context }); }
  async setWidgetState(state: unknown): Promise<void> { await this.updateModelContext({ widgetState: state, visibility: "private" }); }
  async requestDisplayMode(mode: DisplayMode): Promise<void> { await this.rpc("ui/request-display-mode", { mode }); }
  getCapabilities(): HostCapabilities { return { callTool: true, sendMessage: true, updateModelContext: true, widgetState: true, displayModes: ["inline", "pip", "fullscreen"], host: this.kind }; }
}

type OfficialSession = {
  app: MCPApp;
  listener: (snapshot: Partial<AgentAppSnapshot>) => void;
  active: boolean;
  ready: boolean;
  tearingDown: boolean;
  closed: boolean;
  closeRequested: boolean;
};

/** Standard MCP Apps adapter backed by the official ext-apps SDK. */
export class OfficialMCPAdapter implements AgentAppAdapter {
  readonly kind = "standard-mcp" as const;
  private session?: OfficialSession;
  private current(session: OfficialSession) {
    return session.active && !session.tearingDown && this.session === session;
  }
  private close(session: OfficialSession) {
    if (session.closeRequested || session.closed) return;
    session.closeRequested = true;
    void session.app.close().then(() => { session.closed = true; }).catch(() => {
      if (this.current(session)) session.listener({ meta: { connectionError: "The MCP App connection could not be closed." } });
    });
  }
  private ready(capability?: "callTool" | "sendMessage" | "updateModelContext") {
    const session = this.session;
    if (!session || !session.active || !session.ready || session.closed) throw new Error("The MCP App connection is not ready.");
    if (capability && !this.getCapabilities()[capability]) throw new Error(`The host does not support ${capability}.`);
    return session;
  }
  private completed(session: OfficialSession) {
    if (!this.current(session) || !session.ready || session.closed) throw new Error("The MCP App connection changed before the request completed.");
  }
  private publishContext(session: OfficialSession) {
    if (!this.current(session) || session.closed) return;
    const context = session.app.getHostContext(), displayMode = context?.displayMode, theme = context?.theme;
    session.listener({ capabilities: this.getCapabilities(),
      ...(displayMode === "inline" || displayMode === "pip" || displayMode === "fullscreen" ? { displayMode } : {}),
      ...(theme === "light" || theme === "dark" ? { theme } : {}) });
  }
  connect(listener: (snapshot: Partial<AgentAppSnapshot>) => void): () => void {
    if (this.session?.active) throw new Error("The MCP App adapter is already connected.");
    const app = new MCPApp({ name: "mcpcn-app", version: "0.1.0" }, {}, { autoResize: true, strict: true });
    const session = { app, listener, active: true, ready: false, tearingDown: false, closed: false, closeRequested: false };
    this.session = session;
    app.ontoolinput = (input) => { if (this.current(session) && !session.closed) listener({ toolInput: input.arguments }); };
    app.ontoolresult = (result) => {
      if (!this.current(session) || session.closed) return;
      const normalized = result as ToolResult;
      listener({ toolResult: normalized, structuredContent: normalized.structuredContent, meta: normalized._meta });
    };
    app.onhostcontextchanged = () => this.publishContext(session);
    app.onteardown = () => {
      if (this.current(session)) { session.ready = false; session.tearingDown = true; listener({ capabilities: this.getCapabilities() }); }
      return {};
    };
    app.onclose = () => {
      session.ready = false; session.closed = true;
      if (this.current(session)) listener({ capabilities: this.getCapabilities(), meta: { connectionError: "The MCP App connection closed." } });
    };
    listener({ toolInput: undefined, toolResult: undefined, structuredContent: undefined, meta: undefined, widgetState: undefined,
      displayMode: "inline", theme: undefined, capabilities: this.getCapabilities() });
    void app.connect(undefined, { timeout: 10000 }).then(() => {
      if (!this.current(session) || session.closed) return;
      session.ready = true; this.publishContext(session);
    }).catch((error) => {
      if (!this.current(session)) return;
      session.ready = false;
      listener({ capabilities: this.getCapabilities(), meta: { connectionError: error instanceof Error ? error.message : String(error) } });
      session.tearingDown = true;
      this.close(session);
    });
    return () => {
      if (!session.active) return;
      session.active = false; session.ready = false;
      if (this.session === session) this.session = undefined;
      app.ontoolinput = undefined; app.ontoolresult = undefined; app.onhostcontextchanged = undefined; app.onteardown = undefined; app.onclose = undefined;
      this.close(session);
    };
  }
  async callTool(name: string, args: Record<string, unknown> = {}): Promise<ToolResult> {
    const session = this.ready("callTool"), result = await session.app.callServerTool({ name, arguments: args });
    this.completed(session); return result as ToolResult;
  }
  async sendMessage(message: string): Promise<void> {
    const session = this.ready("sendMessage"); await session.app.sendMessage({ role: "user", content: [{ type: "text", text: message }] }); this.completed(session);
  }
  async updateModelContext(context: unknown): Promise<void> {
    const session = this.ready("updateModelContext");
    await session.app.updateModelContext({ content: [{ type: "text", text: typeof context === "string" ? context : JSON.stringify(context) }] }); this.completed(session);
  }
  async setWidgetState(): Promise<void> { throw new Error("Standard MCP Apps does not support private host widget storage."); }
  async requestDisplayMode(mode: DisplayMode): Promise<void> {
    const session = this.ready();
    if (!this.getCapabilities().displayModes.includes(mode)) throw new Error("The host does not support this display mode.");
    const result = await session.app.requestDisplayMode({ mode });
    this.completed(session); session.listener({ displayMode: result.mode });
  }
  getCapabilities(): HostCapabilities {
    const session = this.session, ready = session?.active && session.ready && !session.closed;
    const capabilities = ready ? session.app.getHostCapabilities() : undefined, host = ready ? session.app.getHostContext() : undefined;
    return { callTool: !!capabilities?.serverTools, sendMessage: !!capabilities?.message?.text, updateModelContext: !!capabilities?.updateModelContext?.text,
      widgetState: false, displayModes: ready ? [...(host?.availableDisplayModes ?? ["inline"])] : [], host: this.kind };
  }
}

type OpenAIWindow = Window & { openai?: { callTool?: (name: string, args: Record<string, unknown>) => Promise<ToolResult>; sendFollowUpMessage?: (args: { prompt: string }) => Promise<void>; setWidgetState?: (state: unknown) => Promise<void>; toolInput?: unknown; toolOutput?: ToolResult; widgetState?: unknown; displayMode?: DisplayMode; theme?: "light" | "dark" } };
export class OpenAIAdapter implements AgentAppAdapter {
  readonly kind = "openai" as const;
  private api() { return (window as OpenAIWindow).openai; }
  connect(listener: (snapshot: Partial<AgentAppSnapshot>) => void): () => void {
    const api = this.api();
    listener({ toolInput: api?.toolInput, toolResult: api?.toolOutput, structuredContent: api?.toolOutput?.structuredContent, widgetState: api?.widgetState, displayMode: api?.displayMode ?? "inline", theme: api?.theme === "light" || api?.theme === "dark" ? api.theme : undefined });
    const handler = () => listener({ toolInput: api?.toolInput, toolResult: api?.toolOutput, structuredContent: api?.toolOutput?.structuredContent, widgetState: api?.widgetState, displayMode: api?.displayMode ?? "inline", theme: api?.theme === "light" || api?.theme === "dark" ? api.theme : undefined });
    window.addEventListener("openai:set_globals", handler);
    return () => window.removeEventListener("openai:set_globals", handler);
  }
  async callTool(name: string, args: Record<string, unknown> = {}) { const fn = this.api()?.callTool; if (!fn) throw new Error("Host does not expose callTool"); return fn(name, args); }
  async sendMessage(message: string) { const fn = this.api()?.sendFollowUpMessage; if (!fn) throw new Error("Host does not expose follow-up messages"); await fn({ prompt: message }); }
  async updateModelContext(context: unknown) { await this.sendMessage(typeof context === "string" ? context : JSON.stringify(context)); }
  async setWidgetState(state: unknown) { const fn = this.api()?.setWidgetState; if (!fn) throw new Error("Host does not expose widget state"); await fn(state); }
  getCapabilities(): HostCapabilities { const api = this.api(); return { callTool: !!api?.callTool, sendMessage: !!api?.sendFollowUpMessage, updateModelContext: !!api?.sendFollowUpMessage, widgetState: !!api?.setWidgetState, displayModes: ["inline", "fullscreen"], host: this.kind }; }
}

export class MockAdapter implements AgentAppAdapter {
  readonly kind = "mock" as const;
  calls: Array<{ name: string; args: Record<string, unknown> }> = [];
  private listeners = new Set<(snapshot: Partial<AgentAppSnapshot>) => void>();
  constructor(public snapshot: Partial<AgentAppSnapshot> = {}, private toolHandler?: (name: string, args: Record<string, unknown>) => Promise<ToolResult>) {}
  private publish(next: Partial<AgentAppSnapshot>) { this.snapshot = { ...this.snapshot, ...next }; for (const listener of this.listeners) listener(next); }
  connect(listener: (snapshot: Partial<AgentAppSnapshot>) => void) { this.listeners.add(listener); listener(this.snapshot); return () => { this.listeners.delete(listener); }; }
  async callTool(name: string, args: Record<string, unknown> = {}) { this.calls.push({ name, args }); return this.toolHandler ? this.toolHandler(name, args) : { structuredContent: { ok: true } }; }
  async sendMessage(message: string) { this.publish({ meta: { ...this.snapshot.meta, lastMessage: message } }); }
  async updateModelContext(context: unknown) { this.publish({ meta: { ...this.snapshot.meta, modelContext: context } }); }
  async setWidgetState(widgetState: unknown) { this.publish({ widgetState }); }
  async requestDisplayMode(mode: DisplayMode) {
    if (!this.getCapabilities().displayModes.includes(mode)) throw new Error("The mock host does not support this display mode.");
    this.publish({ displayMode: mode });
  }
  getCapabilities(): HostCapabilities { return { callTool: true, sendMessage: true, updateModelContext: true, widgetState: true, displayModes: ["inline", "fullscreen"], host: this.kind }; }
}

export function detectAdapter(): AgentAppAdapter {
  if (typeof window === "undefined") return new MockAdapter();
  if ((window as OpenAIWindow).openai) return new OpenAIAdapter();
  if (window.parent !== window) return new OfficialMCPAdapter();
  return new MockAdapter();
}

type AgentAppContextValue = AgentAppSnapshot & {
  callTool: AgentAppAdapter["callTool"];
  sendMessage: AgentAppAdapter["sendMessage"];
  updateModelContext: AgentAppAdapter["updateModelContext"];
  setWidgetState: AgentAppAdapter["setWidgetState"];
  requestDisplayMode(mode: DisplayMode): Promise<void>;
};
const AgentAppContext = createContext<AgentAppContextValue | null>(null);
function initialSnapshot(adapter: AgentAppAdapter): AgentAppSnapshot { return { displayMode: "inline", capabilities: adapter.getCapabilities() }; }

export function AgentAppProvider({ children, adapter }: { children: ReactNode; adapter?: AgentAppAdapter }) {
  const connection = useMemo(() => ({ adapter: adapter ?? detectAdapter() }), [adapter]), selected = connection.adapter;
  const activeConnection = useRef<typeof connection | null>(null);
  const [state, setState] = useState(() => ({ connection, snapshot: initialSnapshot(selected) }));
  const snapshot = state.connection === connection ? state.snapshot : initialSnapshot(selected);
  useEffect(() => {
    let active = true; activeConnection.current = connection;
    setState({ connection, snapshot: initialSnapshot(selected) });
    const disconnect = selected.connect?.((next) => {
      if (!active || activeConnection.current !== connection) return;
      setState((current) => active && activeConnection.current === connection ? { connection, snapshot: { ...(current.connection === connection ? current.snapshot : initialSnapshot(selected)), ...next } } : current);
    });
    return () => { active = false; if (activeConnection.current === connection) activeConnection.current = null; disconnect?.(); };
  }, [connection, selected]);
  const value = useMemo<AgentAppContextValue>(() => {
    const current = () => { if (activeConnection.current !== connection) throw new Error("This app provider connection is not active."); };
    return { ...snapshot,
      callTool: async (name, args) => { current(); const result = await selected.callTool(name, args); current(); return result; },
      sendMessage: async (message) => { current(); await selected.sendMessage(message); current(); },
      updateModelContext: async (context) => { current(); await selected.updateModelContext(context); current(); },
      setWidgetState: async (widgetState) => { current(); await selected.setWidgetState(widgetState); current(); },
      requestDisplayMode: async (mode) => {
        current(); if (!selected.requestDisplayMode) throw new Error("The adapter does not support display mode requests.");
        await selected.requestDisplayMode(mode); current();
      }
    };
  }, [connection, selected, snapshot]);
  return <AgentAppContext.Provider value={value}>{children}</AgentAppContext.Provider>;
}

export function useAgentApp() { const value = useContext(AgentAppContext); if (!value) throw new Error("useAgentApp must be used within AgentAppProvider"); return value; }
export function useToolInput<T = unknown>() { return useAgentApp().toolInput as T | undefined; }
export function useToolResult<T = unknown>() { return useAgentApp().toolResult as (ToolResult & { structuredContent?: T }) | undefined; }
export function useHostCapabilities() { return useAgentApp().capabilities; }
export function useWidgetState<T>(initial: T) {
  const app = useAgentApp();
  const [state, setLocalState] = useState<T>((app.widgetState as T | undefined) ?? initial);
  const setState = useCallback(async (next: T | ((current: T) => T)) => { const resolved = typeof next === "function" ? (next as (current: T) => T)(state) : next; setLocalState(resolved); await app.setWidgetState(resolved); }, [app, state]);
  return [state, setState] as const;
}

import { z } from "zod";

export const RiskLevelSchema = z.enum(["low", "medium", "high", "critical"]);
export const ChangeSchema = z.object({
  label: z.string(),
  before: z.union([z.string(), z.number(), z.boolean(), z.null()]).optional(),
  after: z.union([z.string(), z.number(), z.boolean(), z.null()]).optional(),
  confidence: z.number().min(0).max(1).optional(),
  affectedCount: z.number().int().nonnegative().optional()
});
export const SchemaFieldSchema = z.object({
  name: z.string(), label: z.string(), type: z.enum(["text", "textarea", "number", "email", "select", "boolean"]),
  description: z.string().optional(), required: z.boolean().default(false), value: z.unknown().optional(),
  options: z.array(z.object({ label: z.string(), value: z.string() })).optional()
});

import { z } from "zod";
import { ChangeSchema, RiskLevelSchema } from "./schema-common.js";

const identity = z.string().min(1).max(128).refine(value => value.trim() === value && !/[\u0000-\u001f\u007f]/.test(value), "Use a nonblank stable identity without control characters.");
const text = (maximum = 500) => z.string().min(1).max(maximum).refine(value => Boolean(value.trim()) && !/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value), "Use nonblank plain text.");
const review = { reviewId: identity, title: text(240), description: text(2000).optional() };

export const ReviewChangeSchema = ChangeSchema.extend({ id: identity, label: text() })
  .refine(change => change.before !== undefined || change.after !== undefined, "Supply a before or after value.");
const changes = z.array(ReviewChangeSchema).max(100).refine(rows => new Set(rows.map(row => row.id)).size === rows.length, "Change identities must be unique.");

export const ConfirmationPanelSchema = z.object({
  ...review,
  changes,
  requiresExplicitConsent: z.boolean().default(true),
  consentLabel: text().default("I reviewed these changes."),
  confirmLabel: text(120).default("Confirm"),
  cancelLabel: text(120).default("Cancel"),
});
export type ConfirmationPanelData = z.input<typeof ConfirmationPanelSchema>;

export const RiskReviewPanelSchema = z.object({
  ...review,
  risks: z.array(z.object({
    id: identity, label: text(), severity: RiskLevelSchema,
    description: text(2000).optional(), mitigation: text(2000).optional(),
  })).max(100),
  acknowledgedRiskIds: z.array(identity).max(100).default([]),
  affectedCount: z.number().int().nonnegative().optional(),
  rollback: text(2000).optional(),
  acceptLabel: text(120).default("Accept reviewed risks"),
  cancelLabel: text(120).default("Cancel"),
}).superRefine((value, context) => {
  const ids = new Set(value.risks.map(risk => risk.id));
  if (ids.size !== value.risks.length) context.addIssue({ code: "custom", path: ["risks"], message: "Risk identities must be unique." });
  if (new Set(value.acknowledgedRiskIds).size !== value.acknowledgedRiskIds.length || value.acknowledgedRiskIds.some(id => !ids.has(id))) {
    context.addIssue({ code: "custom", path: ["acknowledgedRiskIds"], message: "Acknowledgements must identify unique current risks." });
  }
});
export type RiskReviewPanelData = z.input<typeof RiskReviewPanelSchema>;

export const DiffViewerSchema = z.object({ ...review, changes, selectedChangeId: identity.optional() })
  .refine(value => value.selectedChangeId === undefined || value.changes.some(change => change.id === value.selectedChangeId), "Select a current change.");
export type DiffViewerData = z.input<typeof DiffViewerSchema>;

const evidenceUrl = z.string().min(1).max(2048).refine(value => {
  try {
    const url = new URL(value);
    return value.trim() === value && !/[\u0000-\u0020\u007f]/.test(value)
      && (url.protocol === "https:" || url.protocol === "http:") && !url.username && !url.password;
  } catch { return false; }
}, "Use an absolute HTTP(S) evidence URL without credentials.");
export const SourceEvidencePanelSchema = z.object({
  ...review,
  sources: z.array(z.object({
    id: identity, label: text(), url: evidenceUrl.optional(),
    excerpt: text(5000).optional(), supports: z.array(text()).max(20).default([]),
  })).max(100),
  selectedSourceId: identity.optional(),
}).superRefine((value, context) => {
  const ids = new Set(value.sources.map(source => source.id));
  if (ids.size !== value.sources.length) context.addIssue({ code: "custom", path: ["sources"], message: "Source identities must be unique." });
  if (value.selectedSourceId !== undefined && !ids.has(value.selectedSourceId)) context.addIssue({ code: "custom", path: ["selectedSourceId"], message: "Select a current source." });
});
export type SourceEvidencePanelData = z.input<typeof SourceEvidencePanelSchema>;

import { z } from "zod";

const Id = z.string().min(1).max(120).refine(value => value.trim() === value
  && !/[\u0000-\u001f\u007f]/.test(value)
  && !["__proto__", "prototype", "constructor"].includes(value), "Use a nonempty, safe identifier.");
const Label = z.string().min(1).max(300).refine(value => Boolean(value.trim()), "A label is required.");
const Text = z.string().max(4000);
const Answer = z.union([Text, z.number().finite(), z.boolean()]);
const Scalar = z.union([Answer, z.null()]);
const Evidence = z.object({
  id: Id, label: Label, text: Text.optional(),
  url: z.string().max(2048).refine(value => {
    try { const url = new URL(value); return /^https?:\/\//.test(value) && !/[\u0000-\u0020\u007f]/.test(value) && ["https:", "http:"].includes(url.protocol) && !url.username && !url.password; }
    catch { return false; }
  }, "Evidence links must use HTTP or HTTPS without credentials.").optional()
});
const EvidenceList = z.array(Evidence).max(20).default([]).refine(items => new Set(items.map(item => item.id)).size === items.length, "Evidence IDs must be unique.");
const Common = { id: Id, title: Label, description: Text.optional(), disabled: z.boolean().default(false) };
const Question = z.object({
  id: Id, label: Label, type: z.enum(["text", "textarea", "number", "email", "select", "boolean"]),
  description: Text.optional(), required: z.boolean().default(false), disabled: z.boolean().default(false),
  options: z.array(z.object({ id: Id, label: Label, disabled: z.boolean().default(false) })).max(40).optional(),
  when: z.object({ questionId: Id, equals: Answer }).optional()
}).superRefine((question, ctx) => {
  if (question.type === "select" && (!question.options?.length || new Set(question.options.map(option => option.id)).size !== question.options.length)) {
    ctx.addIssue({ code: "custom", path: ["options"], message: "Select questions need unique, nonempty choices." });
  }
  if (question.type !== "select" && question.options !== undefined) ctx.addIssue({ code: "custom", path: ["options"], message: "Only select questions accept choices." });
});

export const DynamicQuestionFlowSchema = z.object({
  ...Common, questions: z.array(Question).max(40), answers: z.record(Id, Answer).default({}),
  currentQuestionId: Id.optional(), submitLabel: Label.default("Submit answers")
}).superRefine((data, ctx) => {
  const questions = new Map(data.questions.map(question => [question.id, question]));
  if (questions.size !== data.questions.length) ctx.addIssue({ code: "custom", path: ["questions"], message: "Question IDs must be unique." });
  if (data.currentQuestionId !== undefined && !questions.has(data.currentQuestionId)) ctx.addIssue({ code: "custom", path: ["currentQuestionId"], message: "The current question must belong to this flow." });
  for (const [id, value] of Object.entries(data.answers)) {
    const question = questions.get(id);
    if (!question) { ctx.addIssue({ code: "custom", path: ["answers", id], message: "Answers must belong to this flow." }); continue; }
    const valid = question.type === "boolean" ? typeof value === "boolean"
      : question.type === "number" ? value === "" || typeof value === "number"
        : typeof value === "string" && (question.type !== "select" || value === "" || question.options?.some(option => option.id === value));
    if (!valid) ctx.addIssue({ code: "custom", path: ["answers", id], message: "The answer type or choice does not match its question." });
  }
  data.questions.forEach((question, index) => {
    if (!question.when) return;
    const parentIndex = data.questions.findIndex(parent => parent.id === question.when?.questionId);
    if (parentIndex < 0 || parentIndex >= index) ctx.addIssue({ code: "custom", path: ["questions", index, "when"], message: "A condition must reference an earlier question." });
    const parent = questions.get(question.when.questionId), expected = question.when.equals;
    if (parent && !(parent.type === "boolean" ? typeof expected === "boolean" : parent.type === "number" ? typeof expected === "number" : typeof expected === "string" && (parent.type !== "select" || parent.options?.some(option => option.id === expected)))) {
      ctx.addIssue({ code: "custom", path: ["questions", index, "when"], message: "A condition must use a valid answer for its earlier question." });
    }
  });
});
export type DynamicQuestionFlowData = z.input<typeof DynamicQuestionFlowSchema>;

export const ExtractedFieldsReviewSchema = z.object({
  ...Common, fields: z.array(z.object({
    id: Id, label: Label, original: Text, value: Text.default(""), required: z.boolean().default(false),
    disabled: z.boolean().default(false), confidence: z.number().finite().min(0).max(1).optional(), evidence: EvidenceList
  })).max(100), submitLabel: Label.default("Confirm corrections")
}).refine(data => new Set(data.fields.map(field => field.id)).size === data.fields.length, { path: ["fields"], message: "Extracted field IDs must be unique." });
export type ExtractedFieldsReviewData = z.input<typeof ExtractedFieldsReviewSchema>;

export const ComparisonMatrixSchema = z.object({
  ...Common, criteria: z.array(z.object({ id: Id, label: Label, description: Text.optional() })).max(30),
  options: z.array(z.object({
    id: Id, label: Label, description: Text.optional(), values: z.record(Id, Scalar),
    disabled: z.boolean().default(false), evidence: EvidenceList
  })).max(40), selectedId: Id.nullable().optional(), required: z.boolean().default(true), confirmLabel: Label.default("Confirm selection")
}).superRefine((data, ctx) => {
  const criteria = new Set(data.criteria.map(criterion => criterion.id));
  if (criteria.size !== data.criteria.length) ctx.addIssue({ code: "custom", path: ["criteria"], message: "Criterion IDs must be unique." });
  if (new Set(data.options.map(option => option.id)).size !== data.options.length) ctx.addIssue({ code: "custom", path: ["options"], message: "Option IDs must be unique." });
  if (data.options.length && !data.criteria.length) ctx.addIssue({ code: "custom", path: ["criteria"], message: "Options need at least one comparison criterion." });
  data.options.forEach((option, index) => {
    if (Object.keys(option.values).length !== criteria.size || Object.keys(option.values).some(id => !criteria.has(id))) ctx.addIssue({ code: "custom", path: ["options", index, "values"], message: "Each option must provide exactly the declared criteria." });
  });
  if (data.selectedId != null && !data.options.some(option => option.id === data.selectedId)) ctx.addIssue({ code: "custom", path: ["selectedId"], message: "The selection must belong to this comparison." });
});
export type ComparisonMatrixData = z.input<typeof ComparisonMatrixSchema>;

export const ScoreBreakdownSchema = z.object({
  ...Common, criteria: z.array(z.object({
    id: Id, label: Label, score: z.number().finite().min(0).max(1e6),
    maxScore: z.number().finite().positive().max(1e6), weight: z.number().finite().positive().max(1e6).default(1),
    explanation: Text.optional(), evidence: EvidenceList, disabled: z.boolean().default(false)
  }).refine(criterion => criterion.score <= criterion.maxScore, { path: ["score"], message: "A score cannot exceed its maximum." })).max(100),
  selectedCriterionId: Id.nullable().optional(), totalLabel: Label.default("Weighted total")
}).superRefine((data, ctx) => {
  if (new Set(data.criteria.map(criterion => criterion.id)).size !== data.criteria.length) ctx.addIssue({ code: "custom", path: ["criteria"], message: "Scored criterion IDs must be unique." });
  if (data.selectedCriterionId != null && !data.criteria.some(criterion => criterion.id === data.selectedCriterionId)) ctx.addIssue({ code: "custom", path: ["selectedCriterionId"], message: "The reviewed criterion must belong to this scorecard." });
  // At most 100 terms of at most 1e6 * 1e6: weighted sums stay finite and below MAX_SAFE_INTEGER.
  if (data.criteria.some(criterion => criterion.maxScore * criterion.weight === 0)) ctx.addIssue({ code: "custom", path: ["criteria"], message: "Weighted maxima must not underflow to zero." });
});
export type ScoreBreakdownData = z.input<typeof ScoreBreakdownSchema>;

import { z } from "zod";

export type InspectableJSON = null | boolean | number | string | InspectableJSON[] | { [key: string]: InspectableJSON };
export type ToolArguments = { [key: string]: InspectableJSON };

const text = (maximum: number) => z.string().max(maximum).refine(value => value.trim().length > 0, "A nonempty value is required.");
const identity = text(200).refine(value => !/[\u0000-\u001f\u007f]/.test(value), "Control characters are not allowed.");

// Refuse values JSON would omit or reinterpret, and bound recursion before serialization.
function inspectable(value: unknown, objectOnly = false): boolean {
  let count = 0;
  const ancestors = new Set<object>();
  function visit(item: unknown, depth: number): boolean {
    if (++count > 1000 || depth > 8) return false;
    if (item === null || typeof item === "boolean") return true;
    if (typeof item === "number") return Number.isFinite(item);
    if (typeof item === "string") return item.length <= 10000;
    if (typeof item !== "object" || ancestors.has(item) || Object.getOwnPropertySymbols(item).length > 0) return false;
    const array = Array.isArray(item);
    if (!array && Object.getPrototypeOf(item) !== Object.prototype && Object.getPrototypeOf(item) !== null) return false;
    const descriptors = Object.getOwnPropertyDescriptors(item);
    const keys = Object.keys(descriptors).filter(key => !(array && key === "length"));
    if (keys.length > 200 || (array && keys.length !== item.length)) return false;
    ancestors.add(item);
    try {
      return keys.every((key, index) => {
        const descriptor = descriptors[key];
        return key.length <= 256 && key !== "__proto__" && (!array || key === String(index)) && descriptor !== undefined
          && descriptor.enumerable === true && "value" in descriptor && visit(descriptor.value, depth + 1);
      });
    } finally { ancestors.delete(item); }
  }
  try {
    return (!objectOnly || (value !== null && typeof value === "object" && !Array.isArray(value)))
      && visit(value, 0) && JSON.stringify(value).length <= 65536;
  } catch { return false; }
}

const jsonShape: z.ZodType<InspectableJSON, InspectableJSON> = z.lazy(() => z.union([
  z.null(), z.boolean(), z.number(), z.string(), z.array(jsonShape), z.record(z.string(), jsonShape),
]));
// Run the bounded guard before recursive parsing; the JSON shape supplies owned
// parsed values and remains representable by the public JSON Schema exporter.
function guardedJSON(objectOnly: boolean) {
  return z.unknown().superRefine((value, context) => {
    if (!inspectable(value, objectOnly)) context.addIssue({ code: "custom", message: objectOnly ? "Expected a bounded JSON arguments object." : "Expected bounded, finite, acyclic JSON." });
  });
}
const jsonValue = (guardedJSON(false) as z.ZodType<InspectableJSON, InspectableJSON>).pipe(jsonShape);
export { jsonValue as InspectableJSONSchema };
const argumentsObject = (guardedJSON(true) as z.ZodType<ToolArguments, ToolArguments>).pipe(z.record(z.string(), jsonShape));

export const ToolCallCardSchema = z.object({
  id: identity,
  title: text(200).default("Tool call"),
  description: z.string().max(2000).optional(),
  tool: identity,
  arguments: argumentsObject.default({}),
  status: z.enum(["queued", "running", "succeeded", "failed"]),
  result: jsonValue.optional(),
  errorMessage: text(2000).optional(),
  disabled: z.boolean().default(false),
}).superRefine((data, context) => {
  if (data.errorMessage !== undefined && data.status !== "failed") context.addIssue({ code: "custom", path: ["errorMessage"], message: "Failure detail requires failed status." });
});
export type ToolCallCardData = z.input<typeof ToolCallCardSchema>;

export const RetryableErrorStateSchema = z.object({
  id: identity,
  title: text(200).default("Tool request failed"),
  message: text(2000),
  tool: identity,
  arguments: argumentsObject.default({}),
  retryable: z.boolean().default(false),
  attempt: z.number().int().min(1).max(1000).default(1),
  retryLabel: text(120).default("Retry tool"),
  disabled: z.boolean().default(false),
});
export type RetryableErrorStateData = z.input<typeof RetryableErrorStateSchema>;

export const AuthRequiredCardSchema = z.object({
  id: identity,
  title: text(200).default("Authentication required"),
  service: identity,
  description: z.string().max(2000).optional(),
  scopes: z.array(z.object({ id: identity, label: text(200) })).max(20).default([]),
  status: z.enum(["required", "pending", "unavailable"]).default("required"),
  actionLabel: text(120).default("Request access"),
  disabled: z.boolean().default(false),
}).superRefine((data, context) => {
  const seen = new Set<string>();
  data.scopes.forEach((scope, index) => {
    if (seen.has(scope.id)) context.addIssue({ code: "custom", path: ["scopes", index, "id"], message: "Permission identifiers must be distinct." });
    seen.add(scope.id);
  });
});
export type AuthRequiredCardData = z.input<typeof AuthRequiredCardSchema>;

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type ButtonHTMLAttributes, type HTMLAttributes, type ReactNode } from "react";
import type * as React from "react";
import { cn } from "./core";

export function Button({ className, children, ...props }: ButtonHTMLAttributes<HTMLButtonElement>) { return <button className={cn("mcpcn mcpcn-button", className)} {...props}>{children}</button>; }
export function Card({ className, children, ...props }: HTMLAttributes<HTMLDivElement>) { return <section className={cn("mcpcn mcpcn-card", className)} {...props}>{children}</section>; }
export function Badge({ children, risk }: { children: ReactNode; risk?: string }) { return <span className="mcpcn mcpcn-badge" data-risk={risk}>{children}</span>; }
export function Input(props: React.InputHTMLAttributes<HTMLInputElement>) { return <input className={cn("mcpcn mcpcn-input", props.className)} {...props} />; }
export function Textarea(props: React.TextareaHTMLAttributes<HTMLTextAreaElement>) { return <textarea className={cn("mcpcn mcpcn-input", props.className)} {...props} />; }
export function Select(props: React.SelectHTMLAttributes<HTMLSelectElement>) { return <select className={cn("mcpcn mcpcn-input", props.className)} {...props} />; }
export function Alert({ title, children }: { title: string; children?: ReactNode }) { return <div className="mcpcn mcpcn-error" role="alert"><strong>{title}</strong>{children && <div>{children}</div>}</div>; }
export function Skeleton({ className }: { className?: string }) { return <span className={cn("mcpcn", className)} aria-label="Loading" style={{ display: "block", height: 16, borderRadius: 8, background: "var(--mcpcn-line)" }} />; }
export function EmptyState({ title = "Nothing here yet", description }: { title?: string; description?: string }) { return <Card><div className="mcpcn-body" style={{ textAlign: "center" }}><h3 className="mcpcn-title">{title}</h3>{description && <p className="mcpcn-description">{description}</p>}</div></Card>; }
export function Tabs({ items, value, onValueChange, label = "Sections" }: { items: Array<{ value: string; label: string; content: ReactNode }>; value?: string; onValueChange?: (value: string) => void; label?: string }) {
  const id = useId();
  const [local, setLocal] = useState(value ?? items[0]?.value);
  const selected = items.findIndex(item => item.value === (value ?? local));
  const active = selected < 0 ? 0 : selected;
  useEffect(() => {
    if (value === undefined && selected < 0) setLocal(items[0]?.value);
  }, [items, selected, value]);
  const select = (next: string) => { setLocal(next); onValueChange?.(next); };
  return <div className="mcpcn">
    <div className="mcpcn-row" role="tablist" aria-label={label} aria-orientation="horizontal">
      {items.map((item, index) => <Button key={item.value}
        type="button" role="tab" id={`${id}-tab-${index}`} aria-controls={`${id}-panel-${index}`}
        aria-selected={active === index} tabIndex={active === index ? 0 : -1}
        data-variant={active === index ? undefined : "secondary"}
        onClick={() => select(item.value)} onKeyDown={event => {
          let next: number;
          switch (event.key) {
            case "ArrowLeft": next = (index - 1 + items.length) % items.length; break;
            case "ArrowRight": next = (index + 1) % items.length; break;
            case "Home": next = 0; break;
            case "End": next = items.length - 1; break;
            default: return;
          }
          event.preventDefault();
          event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>('[role="tab"]')[next]?.focus();
          select(items[next]!.value);
        }}>{item.label}</Button>)}
    </div>
    {items.map((item, index) => <div key={item.value} role="tabpanel" id={`${id}-panel-${index}`}
      aria-labelledby={`${id}-tab-${index}`} hidden={active !== index} tabIndex={0} style={{ marginTop: 12 }}>
      {active === index ? item.content : null}
    </div>)}
  </div>;
}

type DialogProps = { open: boolean; title: string; children: ReactNode; onClose: () => void };
export function Dialog(props: DialogProps) {
  return props.open ? <OpenDialog {...props} /> : null;
}

function OpenDialog({ title, children, onClose }: DialogProps) {
  const id = useId();
  const dialog = useRef<HTMLDialogElement>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  // Close before unmount removes the dialog, so native focus restoration still applies.
  useLayoutEffect(() => {
    const element = dialog.current!;
    element.showModal();
    heading.current?.focus();
    return () => { element.close(); };
  }, []);
  return <dialog ref={dialog} className="mcpcn mcpcn-dialog" aria-labelledby={id} aria-modal="true"
    onKeyDown={event => {
      const node = event.currentTarget, active = node.ownerDocument.activeElement;
      if (event.key !== "Tab" || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey
        || event.nativeEvent.isComposing || !node.open || !node.matches(":modal") || !node.contains(active)) return;
      const stops = [...node.querySelectorAll<HTMLElement>("button,input,select,textarea,a[href],summary,[tabindex],iframe,[contenteditable='true'],[contenteditable='']")].filter(element => {
        if (!element.isConnected || (element.tabIndex < 0 && !element.isContentEditable) || element.matches(":disabled")
          || element.closest("[hidden],[inert],[aria-hidden='true']") || element.getClientRects().length === 0) return false;
        const style = node.ownerDocument.defaultView?.getComputedStyle(element);
        if (!style || style.display === "none" || style.visibility === "hidden" || style.visibility === "collapse") return false;
        for (let parent = element.parentElement; parent && parent !== node; parent = parent.parentElement) {
          if (parent.tagName === "DETAILS" && !parent.hasAttribute("open") && !parent.querySelector(":scope > summary")?.contains(element)) return false;
        }
        return true;
      });
      // Native iframe tab order can otherwise continue into the embedding host.
      const index = stops.indexOf(active as HTMLElement);
      const next = event.shiftKey ? index <= 0 ? stops.at(-1) : undefined
        : index < 0 || index === stops.length - 1 ? stops[0] : undefined;
      if (next) { event.preventDefault(); next.focus(); }
      else if (stops.length === 0) { event.preventDefault(); heading.current?.focus(); }
    }}
    onCancel={event => { event.preventDefault(); onClose(); }}>
    <Card>
      <div className="mcpcn-header mcpcn-row mcpcn-between">
        <h2 ref={heading} id={id} className="mcpcn-title" tabIndex={-1}>{title}</h2>
        <Button type="button" data-variant="secondary" onClick={onClose} aria-label="Close">×</Button>
      </div>
      <div className="mcpcn-body">{children}</div>
    </Card>
  </dialog>;
}
export function Tooltip({ label, children }: { label: string; children: ReactNode }) { return <span className="mcpcn" title={label} aria-label={label}>{children}</span>; }
export function InvalidPayload({ title, issues, value }: { title?: string; issues?: string[]; value?: unknown }) { return <div className="mcpcn mcpcn-error" role="alert"><strong>{title ?? "This tool result could not be rendered"}</strong><p className="mcpcn-description">Check the component schema and structuredContent payload.</p>{issues?.length ? <ul>{issues.map((i, n) => <li key={n}>{i}</li>)}</ul> : null}{value !== undefined && <details><summary>Developer details</summary><pre className="mcpcn-code">{JSON.stringify(value, null, 2)}</pre></details>}</div>; }

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { ComponentAction, ComponentProps } from "./component-types.js";

/** Parsed component data is JSON-safe; callbacks and UI status are kept outside it. */
export function revisionKey(data: unknown): string {
  const key = JSON.stringify(data);
  if (typeof key !== "string") throw new Error("component_revision_invalid");
  return key;
}

export function Feedback({ busy, error }: { busy?: boolean; error?: string }) {
  return <>{error && <p className="mcpcn-error" role="alert">{error}</p>}
    {busy && <p className="mcpcn-hint" role="status">Working…</p>}</>;
}

/** Dispatch consumer intent; asynchronous work and errors never imply success. */
export function useComponentAction(onAction: ComponentProps<unknown>["onAction"], externalBusy = false) {
  const mounted = useRef(true), active = useRef(false);
  const [pending, setPending] = useState(false), [error, setError] = useState<string>();
  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);
  const send = useCallback((action: ComponentAction) => {
    if (!mounted.current || active.current || externalBusy || !onAction) return;
    active.current = true;
    setError(undefined);
    try {
      const result: unknown = onAction(action);
      if (result && typeof (result as PromiseLike<unknown>).then === "function") {
        setPending(true);
        void Promise.resolve(result).catch(() => {
          if (mounted.current) setError("The action could not be completed. Try again.");
        }).finally(() => {
          active.current = false;
          if (mounted.current) setPending(false);
        });
      } else {
        // Synchronous controlled input callbacks must not disable or blur the input.
        active.current = false;
      }
    } catch {
      active.current = false;
      if (mounted.current) setError("The action could not be completed. Try again.");
    }
  }, [externalBusy, onAction]);
  return { send, busy: externalBusy || pending, error };
}

"use client";

import { useState } from "react";
import {
  ConfirmationPanelSchema, DiffViewerSchema, RiskReviewPanelSchema, SourceEvidencePanelSchema,
  type ConfirmationPanelData, type DiffViewerData, type RiskReviewPanelData, type SourceEvidencePanelData,
} from "./schemas";
