import type { ComponentAction, ComponentProps } from "./component-types.js";

type UIProps = Pick<ComponentProps<unknown>, "className" | "busy" | "error" | "onAction">;
type ReviewData = ParsedOptionSelectorData | ParsedRankingListData;
