  } catch { return null; }
}
const membersOf = (data: ReadyReview): Member[] => "group" in data ? data.group.options : data.list.entries;
const controlledId = (data: ReadyReview) => "group" in data ? data.selectedOptionId : data.selectedEntryId;
const rootKey = (data: ReadyReview) => stableReviewKey("group" in data
  ? { kind: "options", id: data.id, revision: data.revision, groupId: data.group.id, groupRevision: data.group.revision }
  : { kind: "ranking", id: data.id, revision: data.revision, listId: data.list.id, listRevision: data.list.revision });

export interface OptionRankingSelectionState {
  root: string; localId: string | null; selectedId: string | null; memberKey?: string;
}

/** Unrelated members do not invalidate a current private selection. */
export function reconcileOptionRankingSelection(data: ReadyReview, previous?: OptionRankingSelectionState): OptionRankingSelectionState {
  const root = rootKey(data), stored = previous?.root === root ? previous : undefined, members = membersOf(data);
  const old = members.find(member => member.id === stored?.selectedId);
  const replaced = Boolean(stored?.selectedId && stableReviewKey(old ?? null) !== stored.memberKey);
  const localId = stored && !replaced && members.some(member => member.id === stored.localId) ? stored.localId : null;
  const selectedId = controlledId(data) === undefined ? localId : controlledId(data) ?? null;
  const member = members.find(item => item.id === selectedId);
  const next = { root, localId, selectedId, memberKey: member ? stableReviewKey(member) : undefined };
  return stored && stored.localId === next.localId && stored.selectedId === next.selectedId && stored.memberKey === next.memberKey ? stored : next;
}

/** Requested identities participate before a controlled producer acknowledges them. */
export function optionRankingNotificationScope(data: ReadyReview, selectedId: string | null, requestedId: string | null, available: boolean): string {
  const members = membersOf(data);
  return stableReviewKey({ root: rootKey(data), controlled: controlledId(data) !== undefined, available,
    selectedId, selected: members.find(member => member.id === selectedId) ?? null,
    requestedId, requested: members.find(member => member.id === requestedId) ?? null });
}

export function optionRankingIntent(data: ReadyReview, memberId: string | null): Intent | undefined {
  const base = { componentId: data.id, componentRevision: data.revision }, member = membersOf(data).find(item => item.id === memberId);
  if (memberId !== null && !member) return undefined;
  if ("group" in data) {
    const scope = { ...base, groupId: data.group.id, groupRevision: data.group.revision };
    return member ? { type: "select-option", data: { ...scope, optionId: member.id, optionRevision: member.revision } }
      : { type: "clear-option", data: scope };
  }
  const scope = { ...base, listId: data.list.id, listRevision: data.list.revision };
  return member ? { type: "inspect-ranked-option", data: { ...scope, entryId: member.id, entryRevision: member.revision } }
    : { type: "clear-ranked-option", data: scope };
}

function useOptionRankingNotification(data: ReadyReview, selectedId: string | null, onAction: UIProps["onAction"]) {
  const available = Boolean(onAction);
  const current = useRef({ scope: "", requestedId: null as string | null, generation: 0, pendingKey: "", mounted: true });
  const scope = optionRankingNotificationScope(data, selectedId, current.current.requestedId, available);
  const [feedback, setFeedback] = useState<{ scope: string; generation: number; pending: boolean; error?: string }>({ scope, generation: current.current.generation, pending: false });
  if (current.current.scope !== scope) current.current = { ...current.current, scope, generation: current.current.generation + 1, pendingKey: "" };
  useEffect(() => {
    current.current.mounted = true;
    return () => { current.current.mounted = false; current.current.generation += 1; current.current.pendingKey = ""; };
  }, []);
  const send = (intent: ComponentAction | undefined, nextSelectedId: string | null, requestedId: string | null) => {
    if (!intent || !onAction || !current.current.mounted) return;
    const target = optionRankingNotificationScope(data, nextSelectedId, requestedId, available), key = stableReviewKey(intent);
    if (current.current.scope === target && current.current.pendingKey === key) return;
    const generation = current.current.generation + 1;
    current.current = { ...current.current, scope: target, requestedId, generation, pendingKey: key };
    const live = () => current.current.mounted && current.current.scope === target && current.current.generation === generation;
    setFeedback({ scope: target, generation, pending: false });
    try {
      const result: unknown = onAction(intent);
      if (result && typeof (result as PromiseLike<unknown>).then === "function") {
        if (live()) setFeedback({ scope: target, generation, pending: true });
        void Promise.resolve(result).then(() => {
          if (live()) { current.current.pendingKey = ""; setFeedback({ scope: target, generation, pending: false }); }
        }, () => {
          if (live()) { current.current.pendingKey = ""; setFeedback({ scope: target, generation, pending: false, error: "The action could not be completed. Try again." }); }
        });
      } else if (live()) current.current.pendingKey = "";
    } catch {
      if (live()) { current.current.pendingKey = ""; setFeedback({ scope: target, generation, pending: false, error: "The action could not be completed. Try again." }); }
    }
  };
  const visible = feedback.scope === scope && feedback.generation === current.current.generation;
  return { send, pending: visible && feedback.pending, error: visible ? feedback.error : undefined };
}

const valueType = (value: Member["value"]) => value === null ? "null" : Array.isArray(value) ? "array" : typeof value;
function Confidence({ member }: { member: Member }) {
  return <div className="mcpcn-or-confidence"><span>Reported confidence: {member.confidence === undefined ? "Not supplied" : `${member.confidence * 100}%`}</span>
    {member.confidence !== undefined && <meter min={0} max={1} value={member.confidence} aria-label={`Reported confidence: ${member.label}`} aria-valuetext={`${member.confidence * 100}%`} />}</div>;
}
function Rank({ member }: { member: ParsedRankedOption }) {
  return <div className="mcpcn-or-ranking"><span>Reported rank: {member.rank}</span>
    <span>Reported score: {member.score === undefined ? "Not supplied" : member.score}</span>
    {member.scoreLabel !== undefined && <span className="mcpcn-or-text">Score label: {member.scoreLabel}</span>}</div>;
}
function SelectedMember({ member, ranking }: { member: Member; ranking: boolean }) {
  return <div className="mcpcn-or-content" role="region" aria-label={`${ranking ? "Complete ranked option" : "Complete option"} value and evidence: ${member.label}`} tabIndex={0}>
    <h4>{member.label}</h4><p className="mcpcn-hint">Value type: {valueType(member.value)}</p>
    {"rank" in member && <Rank member={member} />}<Confidence member={member} />
    <h5>Complete value</h5><pre className="mcpcn-code" aria-label={ranking ? "Complete ranked option JSON" : "Complete option JSON"}>{JSON.stringify(member.value, null, 2)}</pre>
    <h5>Supplied evidence</h5>{member.evidence.length ? <ul className="mcpcn-or-evidence" aria-label="Supplied evidence">{member.evidence.map(evidence => <li key={evidence.id}>
      <strong>{evidence.label}</strong>{evidence.text !== undefined && <p className="mcpcn-or-text">{evidence.text}</p>}
      {evidence.url !== undefined && <p><a href={evidence.url} target="_blank" rel="noopener noreferrer" referrerPolicy="no-referrer">{evidence.url}</a></p>}
    </li>)}</ul> : <p>No evidence was supplied.</p>}
  </div>;
}
function ReadyView({ data, ...props }: UIProps & { data: ReadyReview }) {
  const [stored, setStored] = useState(() => reconcileOptionRankingSelection(data));
  const state = reconcileOptionRankingSelection(data, stored); if (state !== stored) setStored(state);
  const options = "group" in data, members = membersOf(data), selected = members.find(member => member.id === state.selectedId);
  const controlled = controlledId(data) !== undefined, blocked = controlled && !props.onAction;
  const notification = useOptionRankingNotification(data, state.selectedId, props.onAction);
  const select = (member: Member) => {
    if (blocked) return;
    if (!controlled) setStored({ ...state, localId: member.id, selectedId: member.id, memberKey: stableReviewKey(member) });
    notification.send(optionRankingIntent(data, member.id), controlled ? state.selectedId : member.id, member.id);
  };
  const clear = () => {
    if (blocked || state.selectedId === null) return;
    if (!controlled) setStored({ ...state, localId: null, selectedId: null, memberKey: undefined });
    notification.send(optionRankingIntent(data, null), controlled ? state.selectedId : null, null);
  };
  return <>
    <p className="mcpcn-or-text"><strong>{options ? "Option group: " : "Ranking list: "}</strong>{"group" in data ? data.group.label : data.list.label}</p>
    <p className="mcpcn-hint">{options ? "Select an option to inspect its complete value and supplied evidence." : "Select a ranked option to inspect its complete value and supplied evidence."}</p>
    <p className="mcpcn-hint">Ranks, scores, confidence and evidence are supplied claims, not recommendations or authorization.</p>
    {!members.length ? <p role="status">No ranked options were supplied.</p> : <ul className="mcpcn-or-members" aria-label={options ? "Supplied options" : "Reported ranked options"}>
      {members.map(member => <li key={member.id} className="mcpcn-or-member"><div className="mcpcn-or-summary"><strong>{member.label}</strong>
        <span className="mcpcn-hint">Value type: {valueType(member.value)}</span>{"rank" in member && <Rank member={member} />}<Confidence member={member} />
      </div><Button type="button" data-variant="secondary" aria-label={`${options ? "Select option" : "Inspect ranked option"}: ${member.label}`} aria-pressed={state.selectedId === member.id} disabled={blocked} onClick={() => select(member)}>{options ? "Select option" : "Inspect ranked option"}</Button></li>)}
    </ul>}
    <div><Button type="button" data-variant="secondary" disabled={blocked || state.selectedId === null} onClick={clear}>Clear selection</Button></div>
    {selected ? <SelectedMember key={selected.id} member={selected} ranking={!options} /> : <p role="status">{options ? "No option is selected." : "No ranked option is selected."}</p>}
    {notification.pending && <p role="status" className="mcpcn-hint">Sending selection notification…</p>}<Feedback error={notification.error} />
  </>;
}
function View({ data, kind, ...props }: UIProps & { data: ReviewData; kind: "options" | "ranking" }) {
  return <Card className={["mcpcn-or-root", props.className].filter(Boolean).join(" ")} role="region" aria-label={data.title} aria-busy={Boolean(props.busy)}>
    <header className="mcpcn-header"><h3 className="mcpcn-title">{data.title}</h3>{data.description !== undefined && <p className="mcpcn-description">{data.description}</p>}</header>
    <div className="mcpcn-body mcpcn-stack">{data.state === "ready" ? <ReadyView data={data} {...props} />
      : data.state === "loading" ? <p role="status">{kind === "options" ? "Options are loading." : "Ranked options are loading."}</p>
        : data.state === "empty" ? <p role="status">{kind === "options" ? "No option group was supplied." : "No ranking list was supplied."}</p> : null}
      {data.message !== undefined && <p className="mcpcn-or-text" role={data.state === "error" ? "alert" : undefined}>{data.message}</p>}
      <Feedback busy={props.busy} error={props.error} />
    </div>
  </Card>;
}
export function OptionSelector(props: ComponentProps<OptionSelectorData>) {
  const parsed = OptionSelectorSchema.safeParse(ownData(props));
  if (!parsed.success) return <InvalidPayload title="Option selection data is invalid" issues={parsed.error.issues.map(issue => issue.message)} />;
  return <View data={parsed.data} kind="options" className={props.className} busy={props.busy} error={props.error} onAction={props.onAction} />;
}
export function RankingList(props: ComponentProps<RankingListData>) {
  const parsed = RankingListSchema.safeParse(ownData(props));
  if (!parsed.success) return <InvalidPayload title="Ranking data is invalid" issues={parsed.error.issues.map(issue => issue.message)} />;
  return <View data={parsed.data} kind="ranking" className={props.className} busy={props.busy} error={props.error} onAction={props.onAction} />;
}

import { z } from "zod";

const controls = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/;
const text = (maximum: number) => z.string().max(maximum).refine(value => !controls.test(value), "Supply plain text without unsupported control characters.");
const visible = (maximum: number) => text(maximum).refine(value => Boolean(value.trim()), "Supply visible nonblank text.");
const identity = z.string().regex(/^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/);
const timestamp = z.string().datetime({ offset: true });
const action = z.object({ id: identity, revision: identity, label: visible(300), available: z.boolean() }).strict();
const root = { id: identity, revision: identity, title: visible(300), message: visible(4000), description: text(4000).optional(), reportedAt: timestamp.optional(), action: action.optional() };
const capability = z.object({ id: identity, revision: identity, label: visible(300), reportedSupport: z.enum(["missing", "unsupported", "unknown"]) }).strict();
const scope = z.object({ id: identity, revision: identity, label: visible(300) }).strict();
const unique = (rows: Array<{ id: string }>) => new Set(rows.map(row => row.id)).size === rows.length;
const progress = z.object({ completed: z.number().int().min(0).max(1000000), total: z.number().int().min(1).max(1000000) }).strict()
  .refine(value => value.completed <= value.total, "Completed work cannot exceed the supplied total.");

/** Inspect descriptors before Zod reads a field; no accessor is invoked. */
function plainDTO(value: unknown): boolean {
  let nodes = 0;
  const ancestors = new Set<object>();
  function visit(item: unknown, depth: number): boolean {
    if (++nodes > 4096 || depth > 6) return false;
    if (item === undefined || item === null || typeof item === "boolean") return true;
    if (typeof item === "number") return Number.isFinite(item);
    if (typeof item === "string") return item.length <= 4000;
    if (typeof item !== "object" || ancestors.has(item) || Object.getOwnPropertySymbols(item).length) return false;
    const array = Array.isArray(item), prototype = Object.getPrototypeOf(item);
    if (array ? prototype !== Array.prototype : prototype !== Object.prototype && prototype !== null) return false;
    const descriptors = Object.getOwnPropertyDescriptors(item), keys = Object.keys(descriptors).filter(key => !(array && key === "length"));
    if (keys.length > 64 || array && (descriptors.length?.value !== keys.length || keys.some((key, index) => key !== String(index)))) return false;
    ancestors.add(item);
    try {
      return keys.every(key => {
        const entry = descriptors[key];
        return key.length <= 128 && entry?.enumerable === true && "value" in entry && visit(entry.value, depth + 1);
      });
    } finally { ancestors.delete(item); }
  }
  try { return visit(value, 0); } catch { return false; }
}

function guarded<Output, Input>(schema: z.ZodType<Output, Input>) {
  const guard = z.unknown().superRefine((value, context) => {
    if (!plainDTO(value)) context.addIssue({ code: "custom", message: "Supply a bounded plain DTO without accessors, symbols, cycles or foreign prototypes." });
  }) as z.ZodType<Input, Input>;
  return guard.pipe(schema).superRefine((value, context) => {
    if (context.issues.length) return;
    if (new TextEncoder().encode(JSON.stringify(value)).byteLength > 64 * 1024) {
      context.addIssue({ code: "custom", message: "The complete parsed host state must fit 64 KiB of UTF-8 JSON." });
    }
  });
}

export const BillingGateSchema = guarded(z.object({ ...root, state: z.literal("billing-required"), featureLabel: visible(300), currentPlan: visible(300).optional(), requiredPlan: visible(300).optional() }).strict());
export const UnsupportedHostNoticeSchema = guarded(z.object({ ...root, state: z.literal("unsupported-host"), hostLabel: visible(300), requirements: z.array(capability).min(1).max(20).refine(unique, "Capability identities must be unique.") }).strict());
export const NoDataStateSchema = guarded(z.object({ ...root, state: z.literal("empty"), collectionLabel: visible(300), reason: z.enum(["no-records", "no-matches", "not-yet-provided"]), querySummary: text(4000).optional() }).strict());
export const LoadingBridgeStateSchema = guarded(z.object({ ...root, state: z.literal("waiting"), bridgeLabel: visible(300), phase: z.enum(["connecting", "awaiting-host", "awaiting-tool-result"]), elapsedMs: z.number().int().min(0).max(31536000000).optional(), progress: progress.optional() }).strict());
export const OfflineStateSchema = guarded(z.object({ ...root, state: z.literal("offline"), serviceLabel: visible(300), unsentChanges: z.number().int().min(0).max(1000000).optional() }).strict());
export const PermissionDeniedStateSchema = guarded(z.object({ ...root, state: z.literal("denied"), resourceLabel: visible(300), requesterLabel: visible(300).optional(), scopes: z.array(scope).max(20).refine(unique, "Scope identities must be unique.") }).strict());
export const ExpiredSessionStateSchema = guarded(z.object({ ...root, state: z.literal("expired"), serviceLabel: visible(300), expiredAt: timestamp.optional() }).strict().superRefine((value, context) => {
  if (value.expiredAt && value.reportedAt && Date.parse(value.expiredAt) > Date.parse(value.reportedAt)) {
    context.addIssue({ code: "custom", path: ["expiredAt"], message: "Reported expiry cannot be later than the supplied report timestamp." });
  }
}));

export type BillingGateData = z.input<typeof BillingGateSchema>;
export type UnsupportedHostNoticeData = z.input<typeof UnsupportedHostNoticeSchema>;
export type NoDataStateData = z.input<typeof NoDataStateSchema>;
export type LoadingBridgeStateData = z.input<typeof LoadingBridgeStateSchema>;
export type OfflineStateData = z.input<typeof OfflineStateSchema>;
export type PermissionDeniedStateData = z.input<typeof PermissionDeniedStateSchema>;
export type ExpiredSessionStateData = z.input<typeof ExpiredSessionStateSchema>;
export type HostStateData = BillingGateData | UnsupportedHostNoticeData | NoDataStateData | LoadingBridgeStateData | OfflineStateData | PermissionDeniedStateData | ExpiredSessionStateData;
export type ParsedHostStateData = z.output<typeof BillingGateSchema> | z.output<typeof UnsupportedHostNoticeSchema> | z.output<typeof NoDataStateSchema> | z.output<typeof LoadingBridgeStateSchema> | z.output<typeof OfflineStateSchema> | z.output<typeof PermissionDeniedStateSchema> | z.output<typeof ExpiredSessionStateSchema>;
export type HostStateIntent = { type: "request-billing-review" | "request-compatible-host" | "request-data-refresh" | "request-bridge-recheck" | "request-reconnect" | "request-access-review" | "request-session-renewal"; data: { componentId: string; componentRevision: string; actionId: string; actionRevision: string } };

"use client";

import { useEffect, useRef, useState } from "react";
import {
  BillingGateSchema, UnsupportedHostNoticeSchema, NoDataStateSchema, LoadingBridgeStateSchema,
  OfflineStateSchema, PermissionDeniedStateSchema, ExpiredSessionStateSchema,
  type BillingGateData, type UnsupportedHostNoticeData, type NoDataStateData, type LoadingBridgeStateData,
  type OfflineStateData, type PermissionDeniedStateData, type ExpiredSessionStateData,
  type HostStateData, type ParsedHostStateData, type HostStateIntent,
} from "./schemas";
import { Badge, Button, Card, InvalidPayload } from "./primitives.js";
import { Feedback } from "./component-helpers.js";
import type { ComponentProps } from "./component-types.js";

type UIProps = Pick<ComponentProps<unknown>, "className" | "busy" | "error" | "onAction">;
const requests = {
  "billing-required": "request-billing-review", "unsupported-host": "request-compatible-host", empty: "request-data-refresh",
  waiting: "request-bridge-recheck", offline: "request-reconnect", denied: "request-access-review", expired: "request-session-renewal",
} as const;

function ownData(props: object): unknown {
  try {
    const descriptors = Object.getOwnPropertyDescriptors(props), data: object = Object.create(Object.getPrototypeOf(props));
    for (const key of Reflect.ownKeys(descriptors)) {
      const descriptor = Object.getOwnPropertyDescriptor(descriptors, key)?.value as PropertyDescriptor | undefined;
      if (!descriptor) return null;
      if (typeof key === "string" && (["className", "busy", "error", "onAction"].includes(key) || key === "key" && !descriptor.enumerable)) continue;
      Object.defineProperty(data, key, descriptor);
    }
    return data;
  } catch { return null; }
}

export function hostStateIntent(data: ParsedHostStateData): HostStateIntent | undefined {
  if (!data.action?.available) return undefined;
  return { type: requests[data.state], data: { componentId: data.id, componentRevision: data.revision, actionId: data.action.id, actionRevision: data.action.revision } };
}

/** A callback replacement invalidates its old settlements, even after A/B/A. */
function useHostRequest(onAction: UIProps["onAction"], externalBusy: boolean) {
  const current = useRef({ callback: onAction, generation: 0, active: false, mounted: true });
  if (current.current.callback !== onAction) current.current = { ...current.current, callback: onAction, generation: current.current.generation + 1, active: false };
  const [feedback, setFeedback] = useState<{ generation: number; pending: boolean; error?: string }>({ generation: 0, pending: false });
  useEffect(() => {
    current.current.mounted = true;
    return () => { current.current.mounted = false; current.current.generation += 1; current.current.active = false; };
  }, []);
  const send = (intent: HostStateIntent | undefined) => {
    if (!intent || !onAction || externalBusy || current.current.active || !current.current.mounted) return;
    const generation = current.current.generation + 1;
    current.current.generation = generation; current.current.active = true;
    const live = () => current.current.mounted && current.current.generation === generation && current.current.callback === onAction;
    const settle = (failed: boolean) => {
      if (!live()) return;
      current.current.active = false;
      setFeedback({ generation, pending: false, error: failed ? "The action could not be completed. Try again." : undefined });
    };
    setFeedback({ generation, pending: false });
    try {
      const result: unknown = onAction(intent);
      if (result && typeof (result as PromiseLike<unknown>).then === "function") {
        if (live()) setFeedback({ generation, pending: true });
        void Promise.resolve(result).then(() => settle(false), () => settle(true));
      } else settle(false);
    } catch { settle(true); }
  };
  const visible = feedback.generation === current.current.generation;
  return { send, busy: externalBusy || visible && feedback.pending, error: visible ? feedback.error : undefined };
}

function HostDetails({ data }: { data: ParsedHostStateData }) {
  switch (data.state) {
    case "billing-required": return <><p>Feature: <strong>{data.featureLabel}</strong></p>
      <p>Reported current plan: {data.currentPlan ?? "Not supplied"}</p><p>Reported required plan: {data.requiredPlan ?? "Not supplied"}</p>
      <p className="mcpcn-hint">A billing review request does not create a subscription, charge or purchase.</p></>;
    case "unsupported-host": return <><p>Reported host: <strong>{data.hostLabel}</strong></p><h4>Reported capability requirements</h4>
      <ul>{data.requirements.map(item => <li key={item.id}><strong>{item.label}</strong>: {item.reportedSupport}</li>)}</ul>
      <p className="mcpcn-hint">Host capabilities are supplied by the consumer; this notice does not probe or change the host.</p></>;
    case "empty": return <><p>Collection: <strong>{data.collectionLabel}</strong></p><p>Reported reason: {({ "no-records": "No records", "no-matches": "No matches", "not-yet-provided": "Data not yet provided" })[data.reason]}</p>
      {data.querySummary !== undefined && <p>Reported query: {data.querySummary}</p>}<p className="mcpcn-hint">No data fetch or empty-result inference is performed by this component.</p></>;
    case "waiting": return <><p>Bridge: <strong>{data.bridgeLabel}</strong></p><p>Reported phase: {({ connecting: "Connecting", "awaiting-host": "Awaiting host", "awaiting-tool-result": "Awaiting tool result" })[data.phase]}</p>
      <p>Reported elapsed time: {data.elapsedMs === undefined ? "Not supplied" : `${data.elapsedMs} ms`}</p>
      {data.progress ? <div><p>Reported work: {data.progress.completed} of {data.progress.total}</p><progress value={data.progress.completed} max={data.progress.total} aria-label="Reported bridge work" /></div> : <p>Reported work: Not supplied</p>}
      <p className="mcpcn-hint">Reported work does not establish bridge readiness. No timer or connection is started.</p></>;
    case "offline": return <><p>Service: <strong>{data.serviceLabel}</strong></p><p>Reported unsent changes: {data.unsentChanges === undefined ? "Not supplied" : data.unsentChanges}</p>
      <p className="mcpcn-hint">Connectivity and pending data are consumer reports. This component does not reconnect, send or discard changes.</p></>;
    case "denied": return <><p>Resource: <strong>{data.resourceLabel}</strong></p>{data.requesterLabel !== undefined && <p>Reported requester: {data.requesterLabel}</p>}
      <h4>Reported requested scopes</h4>{data.scopes.length ? <ul>{data.scopes.map(item => <li key={item.id}>{item.label}</li>)}</ul> : <p>No requested scopes were supplied.</p>}
      <p className="mcpcn-hint">Review intent grants no permission and does not change the current access decision.</p></>;
    case "expired": return <><p>Service: <strong>{data.serviceLabel}</strong></p><p>Reported expiry: {data.expiredAt ? <time dateTime={data.expiredAt}>{data.expiredAt}</time> : "Not supplied"}</p>
      <p className="mcpcn-hint">Renewal intent does not inspect, renew or clear a session, collect credentials or redirect.</p></>;
  }
}

function HostStateCard({ data, ui }: { data: ParsedHostStateData; ui: UIProps }) {
  const action = useHostRequest(ui.onAction, Boolean(ui.busy));
  return <Card className={ui.className} role="region" aria-label={data.title} aria-busy={action.busy} style={{ overflowWrap: "anywhere" }}>
    <div className="mcpcn-header"><div className="mcpcn-row mcpcn-between"><h3 className="mcpcn-title">{data.title}</h3><Badge>{data.state}</Badge></div>
      {data.description !== undefined && <p className="mcpcn-description">{data.description}</p>}</div>
    <div className="mcpcn-body mcpcn-stack"><p role="status">{data.message}</p><HostDetails data={data} />
      {data.reportedAt && <p>Reported at: <time dateTime={data.reportedAt}>{data.reportedAt}</time></p>}
      <Feedback busy={action.busy} error={ui.error ?? action.error} />
      {!data.action && <p className="mcpcn-hint">No action was supplied.</p>}</div>
    {data.action && <div className="mcpcn-footer"><Button type="button" disabled={!data.action.available || action.busy || !ui.onAction} onClick={() => action.send(hostStateIntent(data))}>{data.action.label}</Button></div>}
  </Card>;
}

type HostSchema = { safeParse(value: unknown): { success: true; data: ParsedHostStateData } | { success: false; error: { issues: Array<{ message: string }> } } };
function renderHost(props: ComponentProps<HostStateData>, schema: HostSchema) {
  const parsed = schema.safeParse(ownData(props));
  if (!parsed.success) return <InvalidPayload title="Reported host state is invalid" issues={parsed.error.issues.map(issue => issue.message)} />;
